		close(backConnCloseCh)
		s.front.Close()
		s.back.Close()
		s.wg.Wait()
		if c := s.logger.Check(zapcore.DebugLevel, "connection closed"); c != nil {
			c.Write(zap.Duration("duration", time.Since(start)))
		}
		s.stats.finish()
	}()

