	// see: https://github.com/caddyserver/caddy/issues/6273
	if buffered := s.brw.Reader.Buffered(); buffered > 0 {
		data, _ := s.brw.Peek(buffered)
		n, err := s.back.Write(data)
		s.stats.toBackend.Add(int64(n))
