// Cleanup cleans up the resources made by h.
func (h *Handler) Cleanup() error {
	err := h.cleanupConnections()

	// remove hosts from our config from the pool; a host that no config
	// uses anymore has its detached streams closed, the others are kept
	for _, upstream := range h.Upstreams {
		deleted, _ := hosts.Delete(upstream.String())
		if deleted {
			if n, closeErr := detachedStreams.closeUpstream(upstream.String()); n > 0 {
				if c := h.logger.Check(zapcore.DebugLevel, "closed detached streams of removed upstream"); c != nil {
					c.Write(zap.String("upstream", upstream.String()), zap.Int("streams", n), zap.Error(closeErr))
				}
			}
		}
	}

	return err
}

// bodyNopCloserIfNotRead wraps a request body to prevent closing if not read, i.e., when
// dialing to upstream fails.
// It will close the body as normal if the body is read.
type bodyNopCloserIfNotRead struct {
	io.ReadCloser
	read int // tracks the number of bytes read, -1 when first Read returns 0, io.EOF
}

func (b *bodyNopCloserIfNotRead) Read(p []byte) (int, error) {
	if b.read == -1 {
		return 0, io.EOF
	}
	n, err := b.ReadCloser.Read(p)
	// first Read returns 0, io.EOF
	if b.read == 0 && n == 0 && err == io.EOF {
		b.read = -1
	} else {
		b.read += n
	}
	return n, err
}

